        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 466.6666666666667, 'max': 900, 'grade': 'low'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'mean': 7450.0, 'max': 10000, 'grade': 'low'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'mean': 4450.0, 'max': 6400, 'grade': 'low'})
